local Matter = require(game.ReplicatedStorage.Packages.Matter)
local PluginsManager = require(script.Parent.PluginsManager)

local COMPONENTS = {}

for k, v in PluginsManager.GetComponents() do
	table.insert(COMPONENTS, v)
end

local components = {}

for _, name in ipairs(COMPONENTS) do
	components[name] = Matter.component(name)
end

return components
